<script setup>
const props=defineProps({product:Object,catalog:Object});
function select(id){props.product.keycaps=id?{profileId:id}:null;if(id){props.product.trackStock=false;props.product.merch=null;props.product.supplier=null;}}
function toggle(country,enabled){props.product.officeShipping ||= {};if(enabled)props.product.officeShipping[country]={firstItem:0,additionalItem:0};else delete props.product.officeShipping[country];}
</script>
<template>
  <section><h3>Custom keyboard set</h3><label>Keyboard profile<select :value="product.keycaps?.profileId || ''" @change="select($event.target.value)"><option value="">No custom keycap designer</option><option v-for="profile in catalog.keycapProfiles" :key="profile.id" :value="profile.id">{{profile.name}} · {{profile.revision}}</option></select></label>
    <template v-if="product.keycaps"><p class="help-copy">This page uses the selected profile's artwork and choices. Manage profiles in Keycap profiles. After verified payment, the droplet saves the exact design JSON and delivery details for download and places the maker order manually.</p><h4>Customer shipping charges</h4><p class="help-copy">Enter confirmed USD rates for each supported destination. Zero means free shipping. A country left off cannot check out. Different designs of this product share its first/additional item rate.</p><div v-for="country in ['US','CA']" :key="country"><label class="check"><input type="checkbox" :checked="!!product.officeShipping?.[country]" @change="toggle(country,$event.target.checked)" />{{country==='US'?'United States':'Canada'}}</label><div v-if="product.officeShipping?.[country]" class="form-grid"><label>First set USD<input v-model.number="product.officeShipping[country].firstItem" type="number" min="0" step=".01" /></label><label>Each additional set USD<input v-model.number="product.officeShipping[country].additionalItem" type="number" min="0" step=".01" /></label></div></div><p class="notice">Launch checklist: approved physical sample, final retail price, confirmed shipping and production times, working order packet downloads. Then turn off pricing pending, choose Available and publish. Stock tracking stays off for these made-to-order sets.</p></template>
  </section>
</template>
